import copy, random, sys, bisect
sys.path.insert(0, '/workspace/submission')
from utils import run_experiment

class Ref:
    def __init__(self, cfg):
        self.cfg=cfg
        m=cfg['banks']; l=cfg['load_balancers']; r=len(cfg['borders'])-1
        pol=copy.deepcopy(cfg['policy'])
        if pol['kind']=='fifo': pol['time']=0
        elif pol['kind']=='wfq':
            pol['virtual_time']=0
            pol['finish']=[[f,0] for f,_ in sorted(pol['weights'])]
        for t in ['weights','levels']:
            if t in pol: pol[t].sort()
        self.s={'tick':0,'load_balancer':0,'service_bank':0,'sample_progress':0,
            'borders':cfg['borders'][:],
            'counters':[[[int(q<r0%m) for r0 in range(r)] for q in range(m)] for _ in range(l)],
            'history':[0]*r,'policy':pol,
            'queues':[{'fifo':[],'pifo':[],'fifo_bytes':0,'pifo_bytes':0} for _ in range(m)],
            'live':{}}
        self.saves={}; self.log=[]

    def sample(self,i):
        s=self.s;c=s['counters'];r=len(s['history']);m=self.cfg['banks']
        x=[sum(v[j] for bal in c for v in bal) for j in range(r)]
        for bal in c:
            for j in range(r):
                mi=min(v[j] for v in bal)
                for v in bal: v[j]-=mi
        s['history']=[h//2+z for h,z in zip(s['history'],x)]
        s['sample_progress']=0
        return [i,'sample',x,s['history'][:]]

    def remove(self, id):
        s=self.s; p=s['live'].pop(id);q=s['queues'][p['bank']]; st=p['stage']
        q[st].remove(id); q[st+'_bytes']-=p['length'];return p

    def refill(self,q):
        s=self.s; que=s['queues'][q];live=s['live']
        for id in que['fifo'][:self.cfg['refill_batch']]:
            p=live[id];que['fifo'].remove(id);que['fifo_bytes']-=p['length']
            que['pifo'].append(id);que['pifo_bytes']+=p['length'];p['stage']='pifo'
        que['pifo'].sort(key=lambda id:(live[id]['rank'],live[id]['ordinal']))
        ev=[]
        while que['pifo_bytes']>self.cfg['pifo_bytes']:
            id=que['pifo'][-1];self.remove(id);ev.append(id)
        return ev

    def pop(self,q):
        p=self.remove(self.s['queues'][q]['pifo'][0]);pol=self.s['policy']
        if pol['kind']=='wfq':pol['virtual_time']=max(pol['virtual_time'],p['rank'])
        return p

    def run(self):
        for i,e in enumerate(self.cfg['events']):
            s=self.s; cmd=e[0];pol=s['policy'];live=s['live']
            if cmd=='enqueue':
                _,id,f,length,size=e
                k=pol['kind']
                if k=='fifo':pol['time']+=1;rank=pol['time']
                elif k=='sp':rank=dict(pol['levels'])[f]
                elif k=='sff':rank=size
                else:
                    fin=dict(pol['finish']);w=dict(pol['weights'])[f]
                    rank=max(fin[f],pol['virtual_time'])+(length*1048576+w-1)//w
                    fin[f]=rank;pol['finish']=[list(x) for x in sorted(fin.items())]
                r=bisect.bisect_right(s['borders'],min(rank,s['borders'][-1]-1))-1
                l=s['load_balancer'];s['load_balancer']=(l+1)%self.cfg['load_balancers']
                q=min(range(self.cfg['banks']),key=lambda q:s['counters'][l][q][r])
                que=s['queues'][q];accept=que['fifo_bytes']+length<=self.cfg['fifo_bytes']
                if accept:
                    live[id]={'id':id,'rank':rank,'ordinal':i,'flow':f,'length':length,'bank':q,'stage':'fifo','lag':0}
                    que['fifo'].append(id);que['fifo_bytes']+=length
                    s['counters'][l][q][r]+=1;s['sample_progress']+=1
                self.log.append([i,cmd,id,rank,l,r,q,accept])
                if s['sample_progress']==self.cfg['sample_period']:self.log.append(self.sample(i))
                continue
            if cmd=='dequeue':
                for _ in range(e[1]):
                    q=s['service_bank'];t=s['tick'];s['service_bank']=(q+1)%self.cfg['banks'];s['tick']+=1
                    if s['queues'][q]['pifo']:
                        p=self.pop(q);ev=self.refill(q)
                    else:
                        ev=self.refill(q);p=self.pop(q) if s['queues'][q]['pifo'] else None
                    if p is None:row=[i,cmd,t,q,None,None,0,0,ev]
                    else:
                        err=sum(o['rank']<p['rank'] for o in live.values())
                        row=[i,cmd,t,q,p['id'],p['rank'],err,p['lag'],ev]
                        for other in live.values():
                            if other['rank']<p['rank']:other['lag']+=1
                    self.log.append(row)
                continue
            if cmd=='inspect':
                p=live.get(e[1]); row=[i,cmd,e[1],None if p is None else [p['rank'],p['bank'],p['stage'],p['length'],p['flow'],p['lag']]]
            elif cmd=='cancel':
                p=self.remove(e[1]) if e[1] in live else None
                row=[i,cmd,e[1],None,None,None] if p is None else [i,cmd,e[1],p['stage'],p['bank'],p['lag']]
            elif cmd=='save':
                self.saves[e[1]]=copy.deepcopy(s);row=[i,cmd,e[1]]
            elif cmd=='restore':
                self.s=copy.deepcopy(self.saves[e[1]]);row=[i,cmd,e[1]]
            elif cmd=='weight':
                ws=dict(pol['weights']);ws[e[1]]=e[2];pol['weights']=[list(x) for x in sorted(ws.items())]
                row=[i,cmd,*e[1:]]
            elif cmd=='sample':row=self.sample(i)
            elif cmd=='repartition':
                old=s['borders'];new=e[1]
                def project(vec):
                    return [sum(m*max(0,min(v-b,c-b))//(c-b) - m*max(0,min(u-b,c-b))//(c-b)
                                for m,b,c in zip(vec,old,old[1:])) for u,v in zip(new,new[1:])]
                s['counters']=[[project(v) for v in bal] for bal in s['counters']]
                s['history']=project(s['history']);s['borders']=new[:];row=[i,cmd,len(new)-1]
            else:raise ValueError(e)
            self.log.append(row)
        s=self.s
        s['lags']=[[id,p['lag']] for id,p in sorted(s.pop('live').items())]
        return {'log':self.log,'state':s}

def random_case(seed, count=500):
    rng=random.Random(seed);U=rng.choice([20,50,100,2147483647]);b=[0]+sorted(rng.sample(range(1,min(U,100)),rng.randrange(0,10)))+[U]
    cfg={'banks':rng.randint(1,8),'load_balancers':rng.randint(1,8),'fifo_bytes':rng.randint(1,100),
        'pifo_bytes':rng.randint(1,100),'refill_batch':rng.randint(1,32),'sample_period':rng.randint(1,20),
        'borders':b,'policy':{'kind':rng.choice(['fifo','sp','sff','wfq'])},'events':[]}
    p=cfg['policy']
    if p['kind']=='sp':p['levels']=[[f,rng.randrange(0,101)] for f in range(10)]
    if p['kind']=='wfq':p['weights']=[[f,rng.randint(1,1024)] for f in range(10)]
    ids=[];saves=[]
    for i in range(count):
        cmd=rng.choices(['enqueue','dequeue','sample','repartition','cancel','inspect','save','restore','weight'],[35,18,3,3,8,8,3,6,1])[0]
        if cmd=='restore' and not saves:cmd='save'
        if cmd=='weight' and p['kind']!='wfq':cmd='inspect'
        if cmd=='enqueue':
            id=i*21+rng.randrange(21);ids.append(id)
            e=[cmd,id,rng.randrange(10),rng.randrange(1,60),rng.choice([0,1,9,20,100,2147483647])]
        elif cmd=='dequeue':e=[cmd,rng.randrange(1,8)]
        elif cmd=='repartition':e=[cmd,[0]+sorted(rng.sample(range(1,min(U,100)),rng.randrange(0,10)))+[U]]
        elif cmd in ['inspect','cancel']:e=[cmd,rng.choice(ids+[2147483647])]
        elif cmd=='save':
            n=rng.randrange(5)
            if n not in saves:saves.append(n)
            e=[cmd,n]
        elif cmd=='restore':e=[cmd,rng.choice(saves)]
        elif cmd=='weight':e=[cmd,rng.randrange(10),rng.randrange(1,1025)]
        else:e=[cmd]
        cfg['events'].append(e)
    return cfg

if __name__=='__main__':
    for seed in range(1000):
        cfg=random_case(seed)
        actual=run_experiment(cfg);expected=Ref(cfg).run()
        if actual!=expected:
            import json
            for i,(a,b) in enumerate(zip(actual['log'],expected['log'])):
                if a!=b: print('row',i,a,b);break
            else:print('state',actual['state'],expected['state'])
            open('/workspace/tmp/mismatch.json','w').write(json.dumps(cfg))
            raise AssertionError(seed)
        if seed%100==0:print(seed)
    print('differential tests passed')
